def paper(title,authors,year,venue,source,url,doi,topic,abstract,category,**extra):
    x=dict(title=title,titleZh="Not displayed",authors=authors,year=year,venue=venue,source=source,
      category=category,evidence="Publisher or authoritative index record verified",takeaway=abstract,
      theory="See the linked article.",data="See the linked article.",method="See the linked article.",results=abstract,
      relevance="Selected for direct relevance or a clearly marked adjacent mechanism.",
      limitations="See the linked article for design-specific limitations.",url=url,doi=doi,topicIds=[topic],
      abstractMode="unavailable",originalAbstract="",
      abstractUnavailableReason="No permission for verbatim republication was confirmed; this is a faithful English abstract summary based on the linked source.",
      abstractEn=abstract,abstractSource=url,readingPriority="normal",
      priorityReason="Directly relevant or a clearly identified adjacent mechanism.",readingUse="Compact evidence briefing.",
      researchConnection="Relevant to the named research idea.",publicationType="journal",peerReviewed=True,publicationStatus="published")
    x.update(extra); return x

dissertation=[
paper("Relationship Between Cultural Distance and Cross-Cultural Music Video Consumption on YouTube","Young Min Baek",2015,"Social Science Computer Review, 33(6), 730–748","SAGE Journals","https://doi.org/10.1177/0894439314562184","https://doi.org/10.1177/0894439314562184","culture","Using YouTube activity around K-pop videos, national cultural dimensions, and World Bank indicators, the study tests competing cultural-proximity and cultural-exoticism accounts of cross-border media consumption. The results show that cultural distance does not operate as a single universal barrier and that its association with consumption depends on the dimension and context considered.","Dissertation · cross-cultural reception"),
paper("A Window Into the Other Side of the World: Predictors of Viewers’ Interest in Culturally Distant Media","Jiyeon Yeo, Kalkidan Lea Classen, and Jan-Philipp Stein",2026,"Journal of Media Psychology","Hogrefe","https://doi.org/10.1027/1864-1105/a000508","https://doi.org/10.1027/1864-1105/a000508","culture","In a within-subject experiment with 167 Western adults, participants evaluated fictitious films framed as culturally similar or culturally distant. Openness to experience, peer interest, cultural intelligence, and learning motivation predicted interest in culturally distant media, while the broad Western versus non-Western manipulation leaves finer cultural distinctions unresolved.","Dissertation · cross-cultural reception")]

